INSERT INTO itens_orcamento (orcamento_id, descricao, tipo, quantidade, valor_unitario, item_id, criado_em, atualizado_em) SELECT o.id, 'Mão de obra', 'MAO_DE_OBRA', 1, 150.00, NULL, NOW(), NOW() FROM orcamentos o JOIN ordens_servico os ON os.id = o.ordem_servico_id WHERE os.descricao_problema = 'Embreagem patinando (seed2 #08)';
